357	fn heap_list(v: &V) -> Result<Rc<RefCell<Vec<V>>>, E> {
358	    match v {
359	        V::List(l) => Ok(l.clone()),
360	        V::Obj(_) => match inner_of(v) {
361	            Some(V::List(l)) => Ok(l),
362	            _ => type_err("heap argument must be a list".into()),
363	        },
364	        x => type_err(format!("heap argument must be a list, not {}", tn(x))),
365	    }
366	}
367	fn siftdown(h: &mut Vec<V>, start: usize, mut pos: usize) -> Result<(), E> {
368	    let item = h[pos].clone();
369	    while pos > start {
370	        let parent = (pos - 1) >> 1;
371	        if lt(&item, &h[parent])? {
372	            h[pos] = h[parent].clone();
373	            pos = parent;
374	            continue;
375	        }
376	        break;
377	    }
378	    h[pos] = item;
379	    Ok(())
380	}
381	fn siftup(h: &mut Vec<V>, mut pos: usize) -> Result<(), E> {
382	    let end = h.len();
383	    let start = pos;
384	    let item = h[pos].clone();
385	    let mut child = 2 * pos + 1;
386	    while child < end {
387	        let right = child + 1;
388	        if right < end && !lt(&h[child], &h[right])? {
389	            child = right;
390	        }
391	        h[pos] = h[child].clone();
392	        pos = child;
393	        child = 2 * pos + 1;
394	    }
395	    h[pos] = item;
396	    siftdown(h, start, pos)
397	}
