fn m_siftdown(h: &mut Vec<MergeEntry>, start: usize, mut pos: usize, rev: bool) -> Result<(), E> {
    let item = h[pos].clone();
    while pos > start {
        let parent = (pos - 1) >> 1;
        if merge_before(&item, &h[parent], rev)? {
            h[pos] = h[parent].clone();
            pos = parent;
            continue;
        }
        break;
    }
    h[pos] = item;
    Ok(())
}

fn m_siftup(h: &mut Vec<MergeEntry>, mut pos: usize, rev: bool) -> Result<(), E> {
    let end = h.len();
    let start = pos;
    let item = h[pos].clone();
    let mut child = 2 * pos + 1;
    while child < end {
        let right = child + 1;
        if right < end && merge_before(&h[right], &h[child], rev)? {
            child = right;
        }
        h[pos] = h[child].clone();
        pos = child;
        child = 2 * pos + 1;
    }
    h[pos] = item;
    m_siftdown(h, start, pos, rev)
}

