fn merge_lt(a: &MergeEntry, b: &MergeEntry, rev: bool) -> Result<bool, E> {
    if lt(&a.k, &b.k)? {
        return Ok(true);
    }
    if lt(&b.k, &a.k)? {
        return Ok(false);
    }
    // CPython's heap entries are [value, order*direction] tuples: the order
    // tie-break applies only when the values are equal, not when they are
    // unordered (NaN), so the exact tuple comparison is reproduced here.
    if !eq(&a.k, &b.k)? {
        return Ok(false);
    }
    Ok(if rev { a.ord > b.ord } else { a.ord < b.ord })
}

